// === Tab: mySketch ===
var n = 256
var magnify = 2
var field = []

setup = () => {
  createCanvas(n * magnify, n * magnify)
  for (let x = 0; x < n; x++) {
    field[x] = []
  }
  for (let x = 0; x < n; x++) {
    for (let y = 0; y < n; y++) {
      field[x][y] = 0
    }
  }
}

draw = () => {
// update field
  let next = []
  for (let x = 0; x < n; x++) {
    next[x] = []
    for (let y = 0; y < n; y++) {
      next[x][y] = field[x][y]
    }
  }
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      let neighbors = 0
      for (let dy = -3; dy <= 3; dy++) {
        for (let dx = -3; dx <= 3; dx++) {
          if (dx == 0 && dy == 0) continue;
          if (dx * dx + dy * dy <= 10) {
            neighbors += field[(x + dx + n) % n][(y + dy + n) % n]
          }
        }
      }
      if (field[x][y] == 1) {
        if (neighbors < 14 || neighbors > 28) {
          next[x][y] = 0
        }
      } else {
        if (neighbors > 15) {
          next[x][y] = 1
        }
      }
      const d = sqrt((x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / magnify) ** 2 + (y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / magnify) ** 2)
      if (38 < d && d < 40) next[x][y] = 1
    }
  }
  field = next

// show field
  background('white')
  fill('black')
  noStroke()
  for (let x = 0; x < n; x++) {
    for (let y = 0; y < n; y++) {
      if (field[x][y]) rect(x * magnify, y * magnify, magnify, magnify)
    }
  }
}
